const sd = $getWorkflowStaticData('global');
sd.collected = [];
return [
  { json: { catKey: '2309150002', catLabel: '서울 자체', listBase: 'https://youth.seoul.go.kr/infoData/plcyInfo/ctList.do?key=2309150002&tabKind=002', listSuffix: '&orderBy=regYmd+desc&blueWorksYn=N&sw=', detailBase: 'https://youth.seoul.go.kr/infoData/plcyInfo/view.do', detailSuffix: '&tab=001&key=2309150002&tabKind=002' } },
  { json: { catKey: '2309160001', catLabel: '중앙정부/타지역', listBase: 'https://youth.seoul.go.kr/infoData/youthPlcyInfo/list.do?key=2309160001', listSuffix: '', detailBase: 'https://youth.seoul.go.kr/infoData/youthPlcyInfo/view.do', detailSuffix: '&key=2309160001' } }
];

const html = $input.first().json.data;
const pageIdxMatch = html.match(/name="pageIndex"[^>]*value="(\d+)"/);
const pageIndex = pageIdxMatch ? parseInt(pageIdxMatch[1], 10) : 1;

// goView('V202600006') / goView('20260528005400113227') 양 카테고리
const regex = /goView\('([A-Za-z0-9]+)'\)/g;
const ids = [];
let match;
while ((match = regex.exec(html)) !== null) {
  ids.push(match[1]);
}

// 마지막 페이지: fn_egov_link_page(N) 최대값
const pageRegex = /fn_egov_link_page\((\d+)\)/g;
let maxPage = 1;
let pageMatch;
while ((pageMatch = pageRegex.exec(html)) !== null) {
  const p = parseInt(pageMatch[1]);
  if (p > maxPage) maxPage = p;
}

// 현재 카테고리 컨텍스트와 함께 plcyBizId 를 static data 에 누적 (item splitInBatches 없이)
const cat = $('카테고리별 순차 처리').first().json;
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.collected)) sd.collected = [];
for (const id of ids) {
