// 페이지 루프 제어용 요약 1건만 emit
return [{ json: { currentPage: pageIndex, lastPage: maxPage, collected: sd.collected.length, catLabel: cat.catLabel } }];

const html = $input.first().json.data;
const __item = $('정책별 순차 처리').first().json;
const plcyBizId = __item.plcyBizId;
const cat = { detailBase: __item.detailBase, detailSuffix: __item.detailSuffix };

// Helper: th 텍스트로 인접 td 내용 추출 (정제 보강)
// 동기화: __fixtures__/youth-seoul-parse-body/parse-body.mjs 와 동일 알고리즘
function extractByTh(thText) {
  if (!html || !thText) return null;
  const escapedTh = thText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const regex = new RegExp(
    '<th[^>]*>' + escapedTh + '</th>\\s*<td[^>]*>([\\s\\S]*?)</td>',
    'i'
  );
  const match = html.match(regex);
  if (!match) return '';
  return match[1]
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/?[a-zA-Z][^>]*>/g, '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\t/g, '')
    .replace(/^[  ]*-{3,}[  ]*$/gm, '')
    .replace(/-{4,}>/g, '')
    .replace(/\n\s*\n/g, '\n')
    .trim();
}

const REF_SECTIONS = ['관련 사이트', '신청 사이트', '참고 사이트 Ⅰ', '참고 사이트 Ⅱ'];
function extractRefUrls() {
  const urls = []; const seen = new Set();
  for (const th of REF_SECTIONS) {
    const escTh = th.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const re = new RegExp('<th[^>]*>' + escTh + '</th>\\s*<td[^>]*>([\\s\\S]*?)</td>', 'i');
    const m = html.match(re);
    if (!m) continue;
    const hrefRe = /href="(https?:\/\/[^"]+)"/gi;
    let hm;
    while ((hm = hrefRe.exec(m[1])) !== null) {
      const u = hm[1];
      if (seen.has(u)) continue;
      seen.add(u);
      urls.push(u);
    }
  }
  return urls.slice(0, 3);
}

const ATTACHMENT_EXT_PATTERN = /\.(pdf|hwp|hwpx|docx?|xlsx?|zip)(\?|$|#)/i;
function extractSelfAttachments() {
  const out = []; const seen = new Set();
  const linkRe = /<a[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
  let lm;
  while ((lm = linkRe.exec(html)) !== null) {
    const href = lm[1];
    if (!ATTACHMENT_EXT_PATTERN.test(href)) continue;
    const abs = /^https?:\/\//i.test(href)
      ? href
      : 'https://youth.seoul.go.kr' + (href.startsWith('/') ? href : '/' + href);
    if (seen.has(abs)) continue;
    seen.add(abs);
    const text = lm[2].replace(/<[^>]+>/g, '').trim().slice(0, 200);
    out.push({ name: text || abs.split('/').pop(), url: abs });
  }
  return out;
}

const APPLY_SECTION = '신청 사이트';
const REFERENCE_SECTIONS = ['관련 사이트', '참고 사이트 Ⅰ', '참고 사이트 Ⅱ'];
function tdByTh(thText) {
  const escTh = thText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp('<th[^>]*>' + escTh + '</th>\\s*<td[^>]*>([\\s\\S]*?)</td>', 'i');
  const m = html.match(re);
  return m ? m[1] : null;
}
function extractApplyUrl() {
  const td = tdByTh(APPLY_SECTION);
  if (!td) return null;
  const m = td.match(/href="(https?:\/\/[^"]+)"/i);
  return m ? m[1] : null;
}
function extractReferenceSites() {
  const out = []; const seen = new Set();
  for (const th of REFERENCE_SECTIONS) {
    const td = tdByTh(th);
    if (!td) continue;
    const hrefRe = /href="(https?:\/\/[^"]+)"/gi;
    let hm;
    while ((hm = hrefRe.exec(td)) !== null) {
      const u = hm[1];
      if (seen.has(u)) continue;
      seen.add(u);
      out.push({ name: th.replace(/\s*[ⅠⅡ]\s*$/, '').trim(), url: u });
    }
  }
  return out;
}

const BODY_SECTIONS = [
  { th: '정책 소개', label: '사업개요' },
  { th: '주관 기관', label: '주관기관' },
  { th: '운영기관', label: '운영기관' },
  { th: '지원 내용', label: '지원내용' },
  { th: '지원규모', label: '지원규모' },
  { th: '사업운영기간', label: '사업운영기간' },
  { th: '연령', label: '지원대상' },
  { th: '참여요건', label: '참여요건' },
  { th: '학력', label: '학력' },
  { th: '전공요건', label: '전공요건' },
  { th: '취업상태', label: '취업상태' },
  { th: '특화분야 요건', label: '특화분야요건' },
  { th: '추가단서 사항', label: '추가단서' },
  { th: '참여제한 대상', label: '참여제한' },
  { th: '신청절차', label: '신청방법' },
  { th: '심사 및 발표', label: '심사·발표' },
  { th: '제출서류', label: '제출서류' },
  { th: '기타사항', label: '기타사항' },
];
function buildBody() {
  const parts = [];
  for (const s of BODY_SECTIONS) {
    const v = extractByTh(s.th);
    if (v) parts.push(s.label + ': ' + v);
  }
  return parts.join('\n');
}

// 제목 추출: <strong class="title">...</strong>
const titleMatch = html.match(/<strong\s+class="title">([^<]+)<\/strong>/);
const title = titleMatch ? titleMatch[1].trim() : '';

const category = extractByTh('정책 유형');

const periodText = extractByTh('사업신청기간');
let applyStart = null;
let applyEnd = null;
if (periodText) {
  const dateRegex = /(\d{4})\.\s*(\d{1,2})\.\s*(\d{1,2})/g;
  const dates = [];
  let dm;
  while ((dm = dateRegex.exec(periodText)) !== null) {
    const y = dm[1];
    const m = dm[2].padStart(2, '0');
    const d = dm[3].padStart(2, '0');
    dates.push(`${y}-${m}-${d}`);
  }
  if (dates.length >= 1) applyStart = dates[0];
  if (dates.length >= 2) applyEnd = dates[1];
}

const body = buildBody();

const sourceUrl = cat.detailBase + '?plcyBizId=' + plcyBizId + cat.detailSuffix;

const result = {
  source: {
    url: sourceUrl,
    type: 'YOUTH_SEOUL',
    fetchedAt: new Date().toISOString().replace('Z', '')
  },
  rawData: {
    title: title,
    body: body,
    category: category || '복지',
    region: '서울',
    applyStart: applyStart,
    applyEnd: applyEnd,
    _refUrls: extractRefUrls(),
    applyUrl: extractApplyUrl(),
    referenceSites: extractReferenceSites(),
    _selfAttachments: extractSelfAttachments()
  }
};

return [{ json: result }];

// 동기화 책임: n8n/workflows/__fixtures__/enrichment-merge/enrich.mjs 와
// 동일 알고리즘이어야 한다. 한 곳을 수정하면 다른 곳도 같은 변경을 반영해야 한다.
const cheerio = require('cheerio');
const https = require('https');
const http = require('http');

const MAX_URLS = 3;
const MAX_CLEANED_LEN = 16000;
const TEXT_SEPARATOR = '\n\n---\n\n';
const FETCH_TIMEOUT_MS = 10000;
const MAX_RESPONSE_BYTES = 2000000;
const PER_PAGE_CAP = 8000;

function normalizeUrlKey(u) {
  return u.toLowerCase().replace(/\/+$/, '');
}

function selectUrls(policy) {
  // 1) 명시 refUrls[] 가 있으면 우선 사용 (youth-seoul-crawl)
  if (policy && Array.isArray(policy.refUrls)) {
    const seen = new Set();
    const out = [];
    for (const u of policy.refUrls) {
      if (typeof u !== 'string') continue;
      const trimmed = u.trim();
      if (!trimmed) continue;
      const key = normalizeUrlKey(trimmed);
      if (seen.has(key)) continue;
      seen.add(key);
      out.push(trimmed);
      if (out.length >= MAX_URLS) break;
    }
    return out;
  }
  // 2) fallback: 온통청년 키 기반
  const candidates = [policy?.aplyUrlAddr, policy?.refUrlAddr1, policy?.refUrlAddr2]
    .map(s => (typeof s === 'string' ? s.trim() : ''))
    .filter(Boolean);
  const seen = new Set();
  const out = [];
  for (const u of candidates) {
    const key = normalizeUrlKey(u);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(u);
    if (out.length >= MAX_URLS) break;
  }
  return out;
}

function mergeFetchResults(results) {
  if (!Array.isArray(results) || results.length === 0) {
    return { cleanedText: '', extraAttachments: [], status: 'FETCH_FAILED' };
  }
  const ok = results.filter(r => r && r.status == null);
  if (ok.length === 0) {
    const allTooShort = results.length > 0 && results.every(r => r && r.status === 'TOO_SHORT');
    return {
      cleanedText: '',
      extraAttachments: [],
      status: allTooShort ? 'TOO_SHORT' : 'FETCH_FAILED'
    };
  }
  let cleanedText = ok.map(r => r.cleanedText || '').join(TEXT_SEPARATOR);
  if (cleanedText.length > MAX_CLEANED_LEN) cleanedText = cleanedText.slice(0, MAX_CLEANED_LEN);
  const seenAttachments = new Set();
  const extraAttachments = [];
  for (const r of ok) {
    const items = Array.isArray(r.extraAttachments) ? r.extraAttachments : [];
    for (const a of items) {
      if (!a || typeof a.url !== 'string') continue;
      const key = a.url.toLowerCase();
      if (seenAttachments.has(key)) continue;
      seenAttachments.add(key);
      extraAttachments.push(a);
    }
  }
  return { cleanedText, extraAttachments, status: null };
}

function absUrl(href, pageUrl) {
  if (!href) return href;
  if (/^https?:\/\//i.test(href)) return href;
  const m = pageUrl.match(/^(https?:\/\/[^/]+)/);
  const origin = m ? m[1] : '';
  if (href.startsWith('//')) {
    const proto = (pageUrl.match(/^(https?:)/) || ['', 'https:'])[1];
    return proto + href;
  }
  if (href.startsWith('/')) return origin + href;
  return origin + '/' + href.replace(/^\.?\//, '');
}

const ONCLICK_DOWNLOAD_RULES = [
  {
    host: /(^|\.)kofpi\.or\.kr$/i,
    fnName: 'fnNotiDownload',
    buildUrl: (origin, seq) => `${origin}/noti/download.do?fileSeq=${encodeURIComponent(seq)}`,
  },
];

function isDummyHref(href) {
  if (!href) return true;
  const trimmed = href.trim();
  return trimmed === '' || trimmed === '#' || /^javascript:/i.test(trimmed);
}

function escapeRegExp(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function resolveOnclickUrl(onclick, pageUrl) {
  if (!onclick) return null;
  const m = pageUrl.match(/^(https?:\/\/([^/]+))/);
  if (!m) return null;
  const origin = m[1];
  const host = m[2];
  for (const rule of ONCLICK_DOWNLOAD_RULES) {
    if (!rule.host.test(host)) continue;
    const fnRe = new RegExp('\\b' + escapeRegExp(rule.fnName) + "\\s*\\(\\s*['\"]([^'\"]+)['\"]\\s*\\)");
    const am = onclick.match(fnRe);
    if (!am) continue;
    return rule.buildUrl(origin, am[1]);
  }
  return null;
}

function extractCleanedAndAttachments(rawHtml, pageUrl) {
  const $ = cheerio.load(rawHtml);
  $('script, style, nav, footer, aside, header, noscript').remove();
  const root = $('main').first().length ? $('main').first()
            : $('article').first().length ? $('article').first()
            : $('[role="main"]').first().length ? $('[role="main"]').first()
            : $('#content').first().length ? $('#content').first()
            : $('body').first();
  let cleaned = root.text().replace(/\s+/g, ' ').trim();
  if (cleaned.length > PER_PAGE_CAP) cleaned = cleaned.slice(0, PER_PAGE_CAP);

  const seen = new Set();
  const extras = [];
  $('a[href]').each((_, el) => {
    const $a = $(el);
    const href = $a.attr('href') || '';
    const onclick = $a.attr('onclick') || '';
    const text = $a.text().trim();
    const imgAlt = $a.find('img').first().attr('alt') || '';
    const lowerHref = href.toLowerCase();
    const extPattern = /\.(pdf|hwp|hwpx|docx|xlsx|zip)(\?|$|#)/i;
    const hasExt = extPattern.test(href);
    const textHasExt = /\.(pdf|hwp|hwpx|docx|xlsx|zip)$/i.test(text);
    const imgIsFile = /^(pdf|hwp|hwpx|docx|xlsx|zip)$/i.test(imgAlt);
    const hrefHasDownloadKw = /(download|filedown|attach)/i.test(lowerHref);
    const looksLikeFile = hasExt || textHasExt || imgIsFile || (hrefHasDownloadKw && text.length > 0 && text.length < 200);
    if (!looksLikeFile) return;
    let url = absUrl(href, pageUrl);
    if (isDummyHref(href)) {
      const reconstructed = resolveOnclickUrl(onclick, pageUrl);
      if (reconstructed) url = reconstructed;
    }
    if (seen.has(url)) return;
    seen.add(url);
    let name = text;
    if (!name || name.length < 2) {
      name = imgAlt ? `attachment.${imgAlt}` : url.split('/').pop().slice(0, 200);
    }
    name = name.replace(/\s*미리보기\s*$/, '').trim().slice(0, 200);
    extras.push({ name, url });
  });
  return { cleaned, extras };
}

function httpGetText(url, hops) {
  hops = hops || 0;
  if (hops >= 5) return Promise.resolve({ ok: false });
  return new Promise((resolve) => {
    let lib;
    try { lib = url.startsWith('https://') ? https : http; }
    catch (e) { return resolve({ ok: false }); }
    const req = lib.request(url, {
      method: 'GET',
      headers: {
        'User-Agent': 'YouthFit-Bot/1.0 (+https://youthfit.kr/bot)',
        'Accept': 'text/html,application/xhtml+xml',
        'Accept-Encoding': 'identity'
      },
      timeout: FETCH_TIMEOUT_MS
    }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        return httpGetText(absUrl(res.headers.location, url), hops + 1).then(resolve);
      }
      if (res.statusCode < 200 || res.statusCode >= 300) {
        res.resume();
        return resolve({ ok: false });
      }
      const chunks = [];
      let total = 0;
      res.on('data', c => {
        total += c.length;
        if (total > MAX_RESPONSE_BYTES) {
          req.destroy();
          resolve({ ok: false });
          return;
        }
        chunks.push(c);
      });
      res.on('end', () => resolve({ ok: true, body: Buffer.concat(chunks).toString('utf8') }));
    });
    req.on('error', () => resolve({ ok: false }));
    req.on('timeout', () => { req.destroy(); resolve({ ok: false }); });
    req.end();
  });
}

async function fetchAndExtract(url) {
  const res = await httpGetText(url);
  if (!res.ok || !res.body) {
    return { url, status: 'FETCH_FAILED', cleanedText: '', extraAttachments: [] };
  }
  try {
    const { cleaned, extras } = extractCleanedAndAttachments(res.body, url);
    return {
      url,
      status: cleaned.length < 200 ? 'TOO_SHORT' : null,
      cleanedText: cleaned,
      extraAttachments: extras
    };
  } catch (e) {
    return { url, status: 'FETCH_FAILED', cleanedText: '', extraAttachments: [] };
  }
}

const p = $input.first().json;
const urls = selectUrls({ refUrls: Array.isArray(p?.rawData?._refUrls) ? p.rawData._refUrls : [] });

if (urls.length === 0) {
  return [{
    json: {
      ...p,
      _enrichUrl: null,
      _enrichUrls: [],
      _cleanedText: '',
      _extraAttachments: [],
      _enrichmentStatus: 'NO_LINK'
    }
  }];
}

const results = await Promise.all(urls.map(u => fetchAndExtract(u)));
const merged = mergeFetchResults(results);

return [{
  json: {
    ...p,
    _enrichUrl: urls[0],
    _enrichUrls: urls,
    _cleanedText: merged.cleanedText,
    _extraAttachments: merged.extraAttachments,
    _enrichmentStatus: merged.status
  }
}];

const p = $input.first().json;
const e = {
  sourceUrl: (p.rawData._refUrls && p.rawData._refUrls[0]) || null,
  fetchedAt: new Date().toISOString(),
  extractor: 'regex',
  confidence: null,
  status: p._enrichmentStatus === undefined ? 'FETCH_FAILED' : (p._enrichmentStatus ?? 'OK'),
  sections: null,
  extraAttachments: p._extraAttachments || [],
  cleanedText: p._cleanedText || null
};
return [{ json: { ...p, rawData: { ...p.rawData, enrichment: e } } }];

// 동기화 책임: n8n/workflows/__fixtures__/promote-attachments/promote.mjs 와
// 동일 알고리즘이어야 한다. 한 곳을 수정하면 다른 곳도 같은 변경을 반영해야 한다.
const EXT_TO_MEDIA_TYPE = {
  pdf: 'application/pdf',
  hwp: 'application/x-hwp',
  hwpx: 'application/x-hwp',
  doc: 'application/msword',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  xls: 'application/vnd.ms-excel',
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
};

const TEXT_EXT_PATTERN = /\.(pdf|hwpx?|docx?|xlsx?)\b/i;
const PAREN_EXT_PATTERN = /[\(\[]\s*(pdf|hwpx?|docx?|xlsx?)\s*[\)\]]/i;
const PATH_EXT_PATTERN = /(?:^|[^a-zA-Z])(pdf|hwpx?|docx?|xlsx?)(?:$|[^a-zA-Z])/i;
// path-pattern fallback 은 다운로드 의도 키워드가 동반될 때만 활성화한다.
const PATH_DOWNLOAD_KEYWORD_PATTERN = /(?:download|filedown|attach|getfile|board)/i;

function extractExt(url) {
  if (typeof url !== 'string') return null;
  const cleaned = url.split('#')[0].split('?')[0].toLowerCase();
  const dotIdx = cleaned.lastIndexOf('.');
  if (dotIdx === -1) return null;
  return cleaned.slice(dotIdx + 1);
}

function mapExt(ext) {
  if (!ext) return null;
  return EXT_TO_MEDIA_TYPE[ext.toLowerCase()] || null;
}

function extractExtFromText(text) {
  if (typeof text !== 'string' || text.length === 0) return null;
  const m1 = text.match(TEXT_EXT_PATTERN);
  if (m1) return m1[1].toLowerCase();
  const m2 = text.match(PAREN_EXT_PATTERN);
  if (m2) return m2[1].toLowerCase();
  return null;
}

function extractExtFromPath(url) {
  if (typeof url !== 'string') return null;
  const path = url.split('?')[0].split('#')[0]
    .replace(/([a-z])([A-Z])/g, '$1_$2')
    .toLowerCase();
  if (!PATH_DOWNLOAD_KEYWORD_PATTERN.test(path)) return null;
  const m = path.match(PATH_EXT_PATTERN);
  return m ? m[1].toLowerCase() : null;
}

function inferMediaType(item) {
  const fromUrl = mapExt(extractExt(item.url));
  if (fromUrl) return fromUrl;
  const fromName = mapExt(extractExtFromText(item.name));
  if (fromName) return fromName;
  const fromPath = mapExt(extractExtFromPath(item.url));
  if (fromPath) return fromPath;
  return null;
}

const NAME_WHITELIST_PATTERN = /(공고|안내|모집|요강|신청서|계획서|FAQ|Q&A|가이드|설명|일정|참가|운영|평가|선정|채용|지원|보고서|양식|서식|자료|다운로드|붙임|별첨|결과|명단|목록)/i;
const NAME_BLACKLIST_PATTERN = /(로고|배너|아이콘|썸네일|포스터|광고|favicon)/i;
function isInformationalName(name) {
  if (typeof name !== 'string' || !name) return true;
  if (NAME_BLACKLIST_PATTERN.test(name)) return false;
  if (NAME_WHITELIST_PATTERN.test(name)) return true;
  return name.length >= 5;
}

const input = $input.first().json;
const enrichment = input?.rawData?.enrichment;
const enrichmentExtras = Array.isArray(enrichment?.extraAttachments) ? enrichment.extraAttachments : [];
const selfExtras = Array.isArray(input?.rawData?._selfAttachments) ? input.rawData._selfAttachments : [];
const extras = [...enrichmentExtras, ...selfExtras];
if (extras.length === 0) {
  const { _selfAttachments, _refUrls, ...cleanRaw } = input.rawData || {};
  return [{ json: { ...input, rawData: cleanRaw } }];
}
const attachments = Array.isArray(input.rawData.attachments) ? input.rawData.attachments : [];
const existingUrls = new Set(
  attachments
    .map(a => (typeof a.url === 'string' ? a.url.toLowerCase() : null))
    .filter(Boolean)
);
const merged = [...attachments];
for (const ex of extras) {
  if (!ex || typeof ex.url !== 'string') continue;
  const mediaType = inferMediaType(ex);
  if (!mediaType) continue;
  if (!isInformationalName(ex.name)) continue;
  const key = ex.url.toLowerCase();
  if (existingUrls.has(key)) continue;
  merged.push({ name: ex.name, url: ex.url, mediaType });
  existingUrls.add(key);
}
const { _selfAttachments, _refUrls, ...cleanRaw } = input.rawData;
return [{ json: { ...input, rawData: { ...cleanRaw, attachments: merged } } }];

